const renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=.95;renderer.localClippingEnabled=true;host.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight(0xffffff,0x8d9a80,1.9));const sun=new THREE.DirectionalLight(0xfff3da,2.1);sun.position.set(-25,45,20);scene.add(sun);const fill=new THREE.DirectionalLight(0xd7e6f1,1);fill.position.set(25,12,-20);scene.add(fill);
const camera=new THREE.PerspectiveCamera(48,innerWidth/innerHeight,.025,2000);const planCamera=new THREE.OrthographicCamera(-10,10,10,-10,.01,2000);planCamera.up.set(0,0,-1);let activeCamera=camera;
