function applyCutaway(){const enabled=$('#cutaway').checked;$('#cut-controls').hidden=!enabled;clip.constant=Number($('#height').value);$('#height-label').value=`${(clip.constant-box.min.y).toFixed(2)} m`;for(const [m]of materials){m.clippingPlanes=enabled?[clip]:[];m.clipShadows=true;m.needsUpdate=true;}}
async function load(){try{meta=await fetch('./assets/model-info.json').then(r=>r.json());const gltf=await new GLTFLoader(manager).loadAsync('./assets/villa.gltf');model=gltf.scene;model.updateMatrixWorld(true);box=new THREE.Box3().setFromObject(model);center=box.getCenter(new THREE.Vector3());size=box.getSize(new THREE.Vector3());let bestBox=box.clone(),bestVolume=0;for(const child of (model.children[0]?.children||model.children)){const candidate=new THREE.Box3().setFromObject(child),s=candidate.getSize(new THREE.Vector3()),volume=s.x*s.y*s.z;if(volume>bestVolume){bestVolume=volume;bestBox=candidate;}}center=bestBox.getCenter(new THREE.Vector3());fitSize=bestBox.getSize(new THREE.Vector3());extent=Math.max(fitSize.x,fitSize.z);heightBase=box.min.y;
 model.traverse(o=>{if(o.isMesh){if(!o.geometry.attributes.normal)o.geometry.computeVertexNormals();o.frustumCulled=true;meshes.push(o);for(const m of (Array.isArray(o.material)?o.material:[o.material])){if(!materials.has(m)){materials.set(m,{map:m.map,color:m.color.clone()});m.roughness=.85;if(m.transparent)m.depthWrite=false;}}}});scene.add(model);
 grid=new THREE.GridHelper(Math.ceil(extent*1.6),Math.ceil(extent*1.6),0xa4afa0,0xcbd2c5);grid.position.set(center.x,box.min.y-.035,center.z);grid.visible=false;scene.add(grid);
 $('#dimensions').textContent=`${size.x.toFixed(1)} × ${size.z.toFixed(1)} × ${size.y.toFixed(1)} m`;$('#model-detail').textContent=`${meta.materials} materials · ${(meta.statistics.triangles_unique/1000).toFixed(0)}k unique triangles`;
 $('#height').min=box.min.y+.1;$('#height').max=box.max.y+.1;$('#height').value=box.max.y+.1;ready=true;resize();orbitView();$('#status').textContent='Original model · ready';$('#progress').style.width='100%';$('#loading').style.display='none';window.villaExplorer={scene,model,camera,renderer,box,meta,get mode(){return mode},get activeCamera(){return activeCamera},changeMode};
 }catch(e){console.error(e);$('#load-text').textContent='Could not load the villa. Please reload the viewer.';$('#status').textContent='Load failed';}}
load();
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>changeMode(b.dataset.mode));$('#reset').onclick=()=>changeMode('orbit');$('#cutaway').onchange=()=>ready&&applyCutaway();$('#height').oninput=()=>ready&&applyCutaway();$('#grid').onchange=e=>{if(grid)grid.visible=e.target.checked};$('#textures').onchange=e=>{for(const[m,original]of materials){m.map=e.target.checked?original.map:null;m.color.copy(e.target.checked?original.color:new THREE.Color('#d9d8cd'));m.needsUpdate=true}};
$('#help').onclick=()=>$('#help-dialog').showModal();$('#close-help').onclick=()=>$('#help-dialog').close();$('#fullscreen').onclick=async()=>{try{if(!document.fullscreenElement)await document.documentElement.requestFullscreen();else await document.exitFullscreen()}catch{}};
$('#capture').onclick=()=>{renderer.render(scene,activeCamera);const a=document.createElement('a');a.download=`veil-of-light-${mode}.png`;a.href=renderer.domElement.toDataURL('image/png');a.click()};
function activateWalk(){walkActive=true;$('#walk-overlay').hidden=true;renderer.domElement.focus();$('#status').textContent='Walk mode · drag to look';try{const result=renderer.domElement.requestPointerLock?.();if(result?.catch)result.catch(()=>{});}catch{}}
$('#resume').onclick=activateWalk;
renderer.domElement.addEventListener('pointerdown',e=>{if(mode==='walk'){if(!walkActive)activateWalk();dragging=true;lastX=e.clientX;lastY=e.clientY;renderer.domElement.setPointerCapture(e.pointerId)}});
renderer.domElement.addEventListener('pointerup',()=>dragging=false);
renderer.domElement.addEventListener('pointermove',e=>{if(mode==='walk'&&dragging&&!locked){yaw-=(e.clientX-lastX)*.004;pitch=THREE.MathUtils.clamp(pitch-(e.clientY-lastY)*.004,-Math.PI*.47,Math.PI*.47);lastX=e.clientX;lastY=e.clientY;}});
document.addEventListener('pointerlockchange',()=>{locked=document.pointerLockElement===renderer.domElement;if(locked)walkActive=true;$('#walk-overlay').hidden=mode!=='walk'||walkActive;$('#crosshair').hidden=!locked;keys.clear()});
