window.addEventListener('keydown',e=>{if(e.code==='Escape'&&mode==='walk'){walkActive=false;$('#walk-overlay').hidden=false;keys.clear()}if(mode==='walk'&&!['INPUT','BUTTON'].includes(document.activeElement.tagName)){if(['KeyW','KeyA','KeyS','KeyD','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyQ','KeyE','Space'].includes(e.code))e.preventDefault();keys.add(e.code)}});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>keys.clear());
